function Media({path,video=false,className=''}:{path:string,video?:boolean,className?:string}) {
 const [url,setUrl]=useState('');
 useEffect(()=>{let active=true;let value='';blob(path).then(b=>{value=URL.createObjectURL(b);if(active)setUrl(value);else URL.revokeObjectURL(value)}).catch(()=>{});return()=>{active=false;if(value)URL.revokeObjectURL(value)}},[path]);
 return url?(video?<video className={className} controls src={url}/>:<img className={className} src={url} alt="素材画面" loading="lazy"/>):<div className={'media-loading '+className}><ImageIcon size={20}/></div>;
}
function Empty({icon=<FolderOpen size={26}/>,title,children}:{icon?:ReactNode,title:string,children?:ReactNode}){return <div className="empty"><div className="empty-icon">{icon}</div><h3>{title}</h3><div className="muted">{children}</div></div>}
function Field({label,children}:{label:string,children:ReactNode}){return <label className="field"><span>{label}</span>{children}</label>}
function Modal({title,children,onClose,wide=false,className=''}:{title:string,children:ReactNode,onClose:()=>void,wide?:boolean,className?:string}){
 const ref=useRef<HTMLElement>(null),close=useRef(onClose);close.current=onClose;
 useEffect(()=>{const previous=document.activeElement as HTMLElement;const focusable=()=>Array.from(ref.current?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href],summary,[tabindex="0"]')||[]).filter(e=>e.getClientRects().length);focusable()[0]?.focus();const key=(e:KeyboardEvent)=>{if(e.key==='Escape')close.current();if(e.key==='Tab'){const list=focusable();const first=list[0],last=list[list.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}};document.addEventListener('keydown',key);return()=>{document.removeEventListener('keydown',key);previous?.focus()}},[]);
 return <div className="overlay" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><section ref={ref} className={'modal '+(wide?'wide':'')+' '+className} role="dialog" aria-modal="true" aria-label={title}><header><h2>{title}</h2><button className="icon" aria-label="关闭" onClick={onClose}><X size={20}/></button></header>{children}</section></div>}

function MaterialSurface({page,children,onClose}:{page:boolean,children:ReactNode,onClose:()=>void}){return page?<section className="material-library" aria-label="我的素材库">{children}</section>:<Modal title="选择本次素材" wide onClose={onClose}>{children}</Modal>}

function useOperation() {
 const current=useRef({fingerprint:'',key:''});
 return {key:(payload:unknown)=>{const fingerprint=JSON.stringify(payload);if(current.current.fingerprint!==fingerprint||!current.current.key)current.current={fingerprint,key:crypto.randomUUID()};return current.current.key},accepted:()=>{current.current={fingerprint:'',key:''}}};
}

